import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.StringTokenizer;
import java.io.IOException;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author niquefa_diego
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskC solver = new TaskC();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskC {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            char[] s = in.next().toCharArray();
            int c[] = new int[3];
            int pos[][] = new int[3][n];
            for (int i = 0; i < n; ++i) {
                int x = s[i] == 'K' ? 0 : (s[i] == 'V' ? 1 : 2);
                pos[x][c[x]++] = i;
            }

            int dp[][][][] = new int[2][c[0] + 1][c[1] + 1][c[2] + 1];
            for (int[][][] x : dp) for (int[][] y : x) for (int[] z : y) Arrays.fill(z, Integer.MAX_VALUE / 2);
            dp[0][0][0][0] = 0;
            for (int i0 = 0; i0 <= c[0]; ++i0)
                for (int i1 = 0; i1 <= c[1]; ++i1)
                    for (int i2 = 0; i2 <= c[2]; ++i2)
                        for (int isLast1 = 0; isLast1 < 2; ++isLast1) {

                            int cur = dp[isLast1][i0][i1][i2];
                            if (i0 < c[0] && isLast1 == 0) {
                                int swaps = 0, pos0 = pos[0][i0];
                                for (int i = i1; i < c[1] && pos[1][i] < pos0; ++i) swaps++;
                                for (int i = i2; i < c[2] && pos[2][i] < pos0; ++i) swaps++;
                                dp[0][i0 + 1][i1][i2] = Math.min(dp[0][i0 + 1][i1][i2], cur + swaps);
                            }

                            if (i1 < c[1]) {
                                int swaps = 0, pos1 = pos[1][i1];
                                for (int i = i0; i < c[0] && pos[0][i] < pos1; ++i) swaps++;
                                for (int i = i2; i < c[2] && pos[2][i] < pos1; ++i) swaps++;
                                dp[1][i0][i1 + 1][i2] = Math.min(dp[1][i0][i1 + 1][i2], cur + swaps);
                            }

                            if (i2 < c[2]) {
                                int swaps = 0, pos2 = pos[2][i2];
                                for (int i = i0; i < c[0] && pos[0][i] < pos2; ++i) swaps++;
                                for (int i = i1; i < c[1] && pos[1][i] < pos2; ++i) swaps++;
                                dp[0][i0][i1][i2 + 1] = Math.min(dp[0][i0][i1][i2 + 1], cur + swaps);
                            }


                        }

            out.println(Math.min(dp[0][c[0]][c[1]][c[2]], dp[1][c[0]][c[1]][c[2]]));
        }

    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer = null;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

    }
}


